Lemma agsh_piece (M M1 : word -> option byte) (Wp : Z -> Prop) a n :
  (forall i, 0 <= i < 2 ^ 64 -> ~ Wp i -> M1 (Z_to_bv 64 i) = M (Z_to_bv 64 i)) -> (forall i, Wp i -> ~ (BIGSHADOW_LO <= i < BIGSHADOW_HI)) ->
