Definition ssaves (M : word -> option byte) (e18 : Z) : Prop :=
  L5.u64_at RSEGS M (S - 40) RA_SLOW /\ L5.u64_at RSEGS M (S - 48) (v + 8) /\ L5.u64_at RSEGS M (S - 56) ((v + 8) / 8 + SBL) /\ L5.u64_at RSEGS M (S - 64) e18
  /\ L5.u64_at RSEGS M (S - 72) (U 19) /\ L5.u64_at RSEGS M (S - 80) (U 20).
