Lemma tail_S3n (fx : FPState) R M model LK Aw cr' B :
  sk = PESK.SK 0 0 0 ->
  getr R (reg 2) = Z_to_bv 64 (S - 128) -> getr R (reg 8) = Z_to_bv 64 (v + 8) -> getr R (reg 9) = Z_to_bv 64 v -> getr R (reg 18) = Z_to_bv 64 pv ->
  getr R (reg 19) = Z_to_bv 64 ((v + 8) / 8 + SBL) -> getr R (reg 20) = Z_to_bv 64 SBL ->
  (forall i, In i [21; 22; 23; 24]%nat -> getr R (reg i) = Z_to_bv 64 (U i)) -> kept1 R ->
  stok model LK Aw -> mem_ok M -> saves M -> ssaves M 0 -> ri_inv HI ([(B, 1)] ++ LB) FF LK cr' Aw M (vml_of model) ->
  PESKA.sink_atA RSEGS L ar P M v (PESK.SK B 1 1) ->
  L5.u64_at RSEGS M (S - 120) 0 -> L5.u64_at RSEGS M (S - 112) 0 -> L5.u64_at RSEGS M (S - 104) 0 -> L5.u64_at RSEGS M (S - 96) 0 -> L5.u64_at RSEGS M (S - 88) v ->
  PMSP.credit_keep cr0 cr' (PESKA.spa_pot P 0) (PESKA.spa_pot P 1) ->
  srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx R RA_SWAP M model) K.
