(* [comment removed for export] *)
Lemma tail_W2 (fx : FPState) R M model LK Aw cr' B b z c cap' e18 :
  sk = PESK.SK b z c -> z = c -> cap' = PESK.cap_next c -> 0 <= e18 <= 2 ^ 47 -> (c = 0 -> e18 = 0) ->
  getr R (reg 2) = Z_to_bv 64 (S - 208) -> getr R (reg 8) = Z_to_bv 64 (S - 120) -> getr R (reg 9) = Z_to_bv 64 v -> getr R (reg 21) = Z_to_bv 64 SBL -> kept1 R ->
  stok model LK Aw -> mem_ok M -> saves M -> ssaves M e18 -> ri_inv HI (((B, cap') :: PESK.sink_own sk) ++ LB) FF LK cr' Aw M (vml_of model) ->
  hdr M b (b + z) (b + c) ->
  L5.u64_at RSEGS M (S - 120) B -> L5.u64_at RSEGS M (S - 112) (B + z) -> L5.u64_at RSEGS M (S - 104) (B + z + 1) -> L5.u64_at RSEGS M (S - 96) (B + cap') -> L5.u64_at RSEGS M (S - 88) v ->
  L5.u64_at RSEGS M (S - 136) RA_SWAP -> L5.u64_at RSEGS M (S - 144) (v + 8) -> L5.u64_at RSEGS M (S - 152) v -> L5.u64_at RSEGS M (S - 160) pv ->
  L5.u64_at RSEGS M (S - 168) ((v + 8) / 8 + SBL) -> L5.u64_at RSEGS M (S - 176) SBL ->
  L5.u64_at RSEGS M (S - 184) (U 21) -> L5.u64_at RSEGS M (S - 192) (U 22) -> L5.u64_at RSEGS M (S - 200) (U 23) -> L5.u64_at RSEGS M (S - 208) (U 24) ->
  shadow_blk M B cap' -> (0 < c -> PMSPA.accA M b c) -> ablock_range L ar B cap' ->
  PMSP.credit_keep cr0 cr' (PESKA.spa_pot P c) (PESKA.spa_pot P cap') ->
