  getr R (reg 2) = Z_to_bv 64 (S - 128) -> getr R (reg 8) = Z_to_bv 64 (v + 8) -> getr R (reg 9) = Z_to_bv 64 v -> getr R (reg 18) = Z_to_bv 64 pv ->
  getr R (reg 19) = Z_to_bv 64 ((v + 8) / 8 + SBL) -> getr R (reg 20) = Z_to_bv 64 SBL ->
  (forall i, In i [21; 22; 23; 24]%nat -> getr R (reg i) = Z_to_bv 64 (U i)) -> kept1 R ->
  stok model LK Aw -> mem_ok M -> saves M -> ssaves M e18 -> ri_inv HI (((B, cap') :: PESK.sink_own sk) ++ LB) FF LK cr' Aw M (vml_of model) ->
  PESKA.sink_atA RSEGS L ar P M v sk -> PESKA.pv_ok ar FF M S v pv ->
  L5.u64_at RSEGS M (S - 120) B -> L5.u64_at RSEGS M (S - 112) (B + z) -> L5.u64_at RSEGS M (S - 104) (B + z) -> L5.u64_at RSEGS M (S - 96) (B + cap') -> L5.u64_at RSEGS M (S - 88) v ->
  shadow_blk M B cap' -> ablock_range L ar B cap' ->
  PMSP.credit_keep cr0 cr' (PESKA.spa_pot P c) (PESKA.spa_pot P cap') ->
  srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx R RA_SBC M model) K.
Proof using All.
