(* [comment removed for export] *)
Lemma tail_T (fx : FPState) R M model LK Aw cr' B b z c cap' e18 :
  sk = PESK.SK b z c -> z = c -> cap' = PESK.cap_next c -> 0 <= e18 <= 2 ^ 47 -> (c = 0 -> e18 = 0) ->
  getr R (reg 2) = Z_to_bv 64 (S - 192) -> getr R (reg 8) = Z_to_bv 64 (S - 96) -> getr R (reg 9) = Z_to_bv 64 cap' -> getr R (reg 10) = Z_to_bv 64 B ->
  getr R (reg 18) = Z_to_bv 64 (S - 120) -> getr R (reg 19) = Z_to_bv 64 z -> getr R (reg 20) = Z_to_bv 64 ((S - 96) / 8 + SBL) -> getr R (reg 21) = Z_to_bv 64 SBL ->
  (forall i, In i [22; 23; 24]%nat -> getr R (reg i) = Z_to_bv 64 (U i)) -> kept1 R ->
  stok model LK Aw -> mem_ok M -> saves M -> ssaves M e18 -> ri_inv HI (((B, cap') :: PESK.sink_own sk) ++ LB) FF LK cr' Aw M (vml_of model) ->
  PESKA.sink_atA RSEGS L ar P M v sk -> PESKA.pv_ok ar FF M S v pv ->
  L5.u64_at RSEGS M (S - 136) RA_SBC -> L5.u64_at RSEGS M (S - 144) (v + 8) -> L5.u64_at RSEGS M (S - 152) v -> L5.u64_at RSEGS M (S - 160) pv ->
  L5.u64_at RSEGS M (S - 168) ((v + 8) / 8 + SBL) -> L5.u64_at RSEGS M (S - 176) SBL -> L5.u64_at RSEGS M (S - 184) (U 21) -> L5.u64_at RSEGS M (S - 88) v ->
  shadow_blk M B cap' -> ablock_range L ar B cap' ->
  PMSP.credit_keep cr0 cr' (PESKA.spa_pot P c) (PESKA.spa_pot P cap') ->
