Lemma fast_D (fx : FPState) R M model LK Aw b z c :
  sk = PESK.SK b z c -> z < c ->
  getr R (reg 2) = Z_to_bv 64 (S - 32) -> getr R (reg 8) = Z_to_bv 64 (v + 8) -> getr R (reg 9) = Z_to_bv 64 ((v + 8) / 8 + SBL) -> getr R (reg 18) = Z_to_bv 64 (b + z) ->
  (forall i, In i [19; 20; 21; 22]%nat -> getr R (reg i) = Z_to_bv 64 (U i)) -> kept0 R ->
  stok model LK Aw -> mem_ok M -> saves M -> ri_inv HI ([(b, c)] ++ LB) FF LK cr0 Aw M (vml_of model) ->
  PESKA.sink_atA RSEGS L ar P M v (PESK.SK b (z + 1) c) ->
