(* [comment removed for export] *)
Lemma fast_C (fx : FPState) R M model LK Aw b z c :
  sk = PESK.SK b z c -> z < c ->
  getr R (reg 2) = Z_to_bv 64 (S - 80) -> getr R (reg 18) = Z_to_bv 64 (b + z) ->
  (forall i, In i [19; 20; 21; 22]%nat -> getr R (reg i) = Z_to_bv 64 (U i)) -> kept0 R ->
  stok model LK Aw -> mem_ok M -> saves M -> ri_inv HI ([(b, c)] ++ LB) FF LK cr0 Aw M (vml_of model) ->
  PESKA.sink_atA RSEGS L ar P M v (PESK.SK b (z + 1) c) ->
  L5.u64_at RSEGS M (S - 40) RA_COE -> L5.u64_at RSEGS M (S - 48) (v + 8) -> L5.u64_at RSEGS M (S - 56) ((v + 8) / 8 + SBL) ->
  srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx R RA_TXD M model) K.
