(* [comment removed for export] *)
Lemma fast_B (fx : FPState) R M model LK Aw b z c :
  sk = PESK.SK b z c -> z < c ->
  getr R (reg 2) = Z_to_bv 64 (S - 80) -> getr R (reg 8) = Z_to_bv 64 pv -> getr R (reg 9) = Z_to_bv 64 SBL -> getr R (reg 18) = Z_to_bv 64 (b + z) ->
  (forall i, In i [19; 20; 21; 22]%nat -> getr R (reg i) = Z_to_bv 64 (U i)) -> kept0 R ->
  stok model LK Aw -> mem_ok M -> saves M -> ri_inv HI ([(b, c)] ++ LB) FF LK cr0 Aw M (vml_of model) ->
  PEASKAN.bhdr RSEGS M v b z c -> PMSPA.accA M b (z + 1) -> PMSPA.annA M b (z + 1) c ->
  PESKA.pv_ok ar FF M S v pv ->
  L5.u64_at RSEGS M (S - 80) v -> L5.u64_at RSEGS M (S - 72) (b + z) -> L5.u64_at RSEGS M (S - 64) (b + z + 1) ->
  L5.u64_at RSEGS M (S - 56) ((v + 8) / 8 + SBL) -> L5.u64_at RSEGS M (S - 48) (v + 8) -> L5.u64_at RSEGS M (S - 40) RA_COE ->
  srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx R RA_ANNI M model) K.
